import { expect, test } from '@playwright/test';

// Smallest valid zip (empty archive) — see the trace attachment below.
const EMPTY_ZIP = Buffer.from('UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA==', 'base64');

// 1x1 red pixel — exercises inline image rendering in the report.
const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64',
);

// 120×80 card mockups: the button moves and changes color between expected and
// actual; diff marks the changed pixels red (generated by scripts, real PNGs).
const EXPECTED_PNG = Buffer.from(
  '',
  'base64',
);
const ACTUAL_PNG = Buffer.from(
  '',
  'base64',
);
const DIFF_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAHgAAABQCAIAAABd+SbeAAAAkklEQVR42u3QwQkAMAgEQYuz/1ZSgqkhj4jILPc/mCi1FAhAgxZo0KAFGrRAgwYt0KAFGjRogQYt0KBBCzRogQYNWqBBCzRo0AINWqBBgxZo0AINGrRAgxZo0KAFGrRAgwatgdAn89Nm/oIGDRo0aNCgQYMGDRo0aNCgd0MLNGjQAg1aoEGDFmjQAg0atECD1lMXchDM5p+g5kMAAAAASUVORK5CYII=',
  'base64',
);

test.describe('beacon demo suite', () => {
  test('passes with steps and attachments @smoke', async ({}, testInfo) => {
    await test.step('outer step', async () => {
      await test.step('inner assertion', async () => {
        expect(1 + 1).toBe(2);
      });
    });
    await testInfo.attach('greeting', {
      body: 'hello from beacon',
      contentType: 'text/plain',
    });
    await testInfo.attach('tiny screenshot', { body: TINY_PNG, contentType: 'image/png' });
    await testInfo.attach('network.har', {
      body: JSON.stringify({
        log: {
          entries: [
            {
              request: { method: 'GET', url: 'https://api.demo-shop.dev/v1/cart' },
              response: { status: 200, content: { size: 1420 } },
              time: 82.4,
            },
            {
              request: { method: 'POST', url: 'https://api.demo-shop.dev/v1/checkout' },
              response: { status: 502, content: { size: 96 } },
              time: 1290.1,
            },
          ],
        },
      }),
      contentType: 'application/json',
    });
    await testInfo.attach('axe-scan', {
      body: JSON.stringify({
        violations: [
          {
            id: 'color-contrast',
            impact: 'serious',
            help: 'Elements must meet minimum color contrast ratio thresholds',
            nodes: [{}, {}, {}],
          },
          {
            id: 'button-name',
            impact: 'critical',
            help: 'Buttons must have discernible text',
            nodes: [{}],
          },
        ],
      }),
      contentType: 'application/json',
    });
  });

  test('fails as expected (demonstrates failure capture)', async ({}, testInfo) => {
    test.fail(true, 'intentional failure so the demo run still exits green');
    testInfo.annotations.push({ type: 'issue', description: '42' });
    testInfo.annotations.push({ type: 'severity', description: 'critical' });
    testInfo.annotations.push({ type: 'owner', description: 'demo' });
    // Placeholder zip standing in for a real trace (real ones come from
    // browser projects with tracing on) — exercises the trace card + link-out.
    await testInfo.attach('trace', { body: EMPTY_ZIP, contentType: 'application/zip' });
    expect(2 + 2, 'intentionally wrong assertion').toBe(5);
  });

  test('flaky: fails first, passes on retry @regression', async ({}, testInfo) => {
    testInfo.annotations.push({ type: 'severity', description: 'normal' });
    testInfo.annotations.push({ type: 'requirement', description: 'REQ-201' });
    expect(testInfo.retry, 'fails on the first attempt to demonstrate flakiness').toBeGreaterThan(
      0,
    );
  });

  test('skipped for demo purposes', async () => {
    test.skip(true, 'demonstrates the skip annotation');
  });

  // Simulates the attachment triple toHaveScreenshot produces on a mismatch,
  // so the report's visual-diff viewer has real images to render.
  test('visual comparison of hero card', async ({}, testInfo) => {
    testInfo.annotations.push({ type: 'requirement', description: 'REQ-101' });
    testInfo.annotations.push({
      type: 'description',
      description:
        'Compares the hero card against its golden screenshot.\nRegenerate goldens with --update-snapshots.',
    });
    await testInfo.attach('hero-expected.png', { body: EXPECTED_PNG, contentType: 'image/png' });
    await testInfo.attach('hero-actual.png', { body: ACTUAL_PNG, contentType: 'image/png' });
    await testInfo.attach('hero-diff.png', { body: DIFF_PNG, contentType: 'image/png' });
    expect(EXPECTED_PNG.equals(ACTUAL_PNG), 'images differ by design').toBe(false);
  });

  test('scenario: customer applies a discount code', async ({}, testInfo) => {
    testInfo.annotations.push({ type: 'requirement', description: 'REQ-101' });
    await test.step('Given a signed-in customer with items in the cart', async () => {
      expect(true).toBe(true);
    });
    await test.step('When they apply the code WELCOME10', async () => {
      expect('WELCOME10').toHaveLength(9);
    });
    await test.step('Then the total is reduced by 10 percent', async () => {
      expect(90).toBeLessThan(100);
    });
  });

  test('slow test with stdout', async ({}, testInfo) => {
    test.slow();
    testInfo.annotations.push({ type: 'budget', description: '200ms' });
    await testInfo.attach('beacon:metrics', {
      body: JSON.stringify({ renderMs: 212, apiLatencyMs: 87 }),
      contentType: 'application/json',
    });
    console.log('some captured stdout');
    console.log('auth token secret-12345 should never appear in the report');
    await new Promise((resolve) => setTimeout(resolve, 300));
    expect(true).toBe(true);
  });
});
